head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====

scwin.SORT_BTN_CLASS = "w2grid_head_sort_div_main_btn_accessibility";
scwin.focusSeq = 0;

// 포커스가 옮겨간 요소를 사람이 읽을 수 있는 형태로 표현
scwin.describeElement = function (objEl) {
    if (!objEl) { return "(없음)"; }
    var strClass = (typeof objEl.className === "string") ? objEl.className : "";
    var strId = objEl.id || "(id 없음)";
    var strTag = (objEl.tagName || "").toLowerCase();

    if (strClass.indexOf(scwin.SORT_BTN_CLASS) > -1) {
        return "정렬 Header button (" + strTag + "." + scwin.SORT_BTN_CLASS + ", " + strId + ")";
    }
    if (strId.indexOf("_cell_") > -1) {
        return "Body Cell (" + strTag + ", " + strId + ")";
    }
    return strTag + " (" + strId + ")";
};

// Tab 포커스 추적 시작 : 이 버튼을 클릭한 뒤 Tab 키를 누르면 포커스가 이동한 요소가 결과창에 쌓인다
scwin.btn_startTrace_onclick = function (e) {
    if (scwin.focusHandler) {
        document.removeEventListener("focusin", scwin.focusHandler, true);
    }
    scwin.focusSeq = 0;

    scwin.focusHandler = function (evt) {
        var objGrid = document.getElementById("mf_target1");
        if (!objGrid || !evt.target || !objGrid.contains(evt.target)) {
            return;
        }
        scwin.focusSeq = scwin.focusSeq + 1;
        var strClass = (typeof evt.target.className === "string") ? evt.target.className : "";
        scwin.setReturnValue("[포커스 이동 " + scwin.focusSeq + "] " + scwin.describeElement(evt.target)
            + "  정렬 Header button 도달 : " + (strClass.indexOf(scwin.SORT_BTN_CLASS) > -1 ? "예" : "아니오"));
    };
    document.addEventListener("focusin", scwin.focusHandler, true);

    scwin.setReturnValue("[Tab 포커스 추적 시작] 이제 Tab 키를 눌러 GridView 안으로 포커스를 옮긴다");
};

// 정렬 실행 결과 (정렬 Header button 에서 Space / Enter 를 누를 때마다 발생)
scwin.target1_onsort = function (sortInfo) {
    var objGrid = $p.getComponentById("target1");
    var arr = [];
    for (var i = 0; i < objGrid.getRowCount(); i++) {
        arr.push(objGrid.getCellData(i, 0));
    }
    scwin.setReturnValue("[정렬 순환] sortOrder=" + sortInfo.sortOrder + " (1 오름차순 / -1 내림차순 / 0 원래대로), col1 표시순서=" + arr.join(","));
};
